const SUPABASE_URL = 'https://SEU-PROJETO.supabase.co';
const SERVICE_ROLE = 'COLE_A_SERVICE_ROLE_AQUI';
const EMAIL_DESTINO = 'COLE_O_EMAIL_DO_RAFAEL';

const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const atual = body.record || {};
const anterior = body.old_record || {};

if (body.type !== 'UPDATE' || atual.status !== 'concluido' || anterior.status === 'concluido' || !atual.id) {
  return [];
}

return [{
  json: {
    pedido_id: atual.id,
    supabase_url: String(SUPABASE_URL).replace(/\/$/, ''),
    service_role: SERVICE_ROLE,
    email_destino: EMAIL_DESTINO,
  },
}];

function reais(valor) {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(valor) || 0);
}
function quando(iso) {
  if (!iso) return 'sem data';
  return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Sao_Paulo' }).format(new Date(iso));
}
function numeroPedido(numero) {
  return '#' + String(numero).padStart(3, '0');
}
const FORMAS = {
  pix: 'Pix',
  cartao: 'Cartão',
  boleto: 'Boleto',
  dinheiro: 'Dinheiro',
  transferencia: 'Transferência',
  a_combinar: 'A combinar',
};

const payload = $input.first().json;
const lista = Array.isArray(payload) ? payload : [payload];
const pedido = lista[0];
if (!pedido || !pedido.id) {
  throw new Error('Pedido concluído não encontrado para registrar o faturamento.');
}
const cliente = pedido.clientes && pedido.clientes.nome ? pedido.clientes.nome : 'Cliente não identificado';
const numero = numeroPedido(pedido.numero);
const valor = reais(pedido.valor_total);
const pagamento = FORMAS[pedido.forma_pagamento] || 'Não informada';

return [{
  json: {
    para: $('Filtrar concluido').first().json.email_destino,
    assunto: 'Faturado ' + numero + ' — ' + cliente + ' — ' + valor + ' (' + pagamento + ')',
    corpo: [
      'Pedido faturado.',
      '',
      'Pedido: ' + numero,
      'Cliente: ' + cliente,
      'Valor: ' + valor,
      'Pagamento: ' + pagamento,
      'Data: ' + quando(pedido.concluido_em || pedido.updated_at),
    ].join('\n'),
  },
}];

const item = $input.first().json;
const mensagem = (item && item.error && item.error.message) || item.message || JSON.stringify(item);
throw new Error('Automação 3 falhou e não enviou o e-mail de faturamento: ' + mensagem);
